UPDATE auth.users SET confirmation_token = COALESCE(confirmation_token, ''), recovery_token = COALESCE(recovery_token, ''), email_change_token_new = COALESCE(email_change_token_new, '') WHERE confirmation_token IS NULL OR recovery_token IS NULL OR email_change_token_new IS NULL; ALTER TABLE auth.users ALTER COLUMN confirmation_token SET DEFAULT ''; ALTER TABLE auth.users ALTER COLUMN recovery_token SET DEFAULT ''; ALTER TABLE auth.users ALTER COLUMN email_change_token_new SET DEFAULT ''; 